class Solution {
    fun minFallingPathSum(grid:Array<IntArray>):Int{
        val n=grid.size;
        if(n==1)return grid[0][0];
        var dp=grid[0].copyOf();
        for(row in 1 until n){
            var first=Int.MAX_VALUE;
            var second=Int.MAX_VALUE;
            var firstColumn=-1;
            for(column in 0 until n)if(dp[column]<first){
                second=first;
                first=dp[column];
                firstColumn=column
            }else if(dp[column]<second)second=dp[column];
            dp=IntArray(n){
                column->grid[row][column]+if(column==firstColumn)second else first
            }
        };
        return dp.min()
    }
}

